{
  "verses": [
    {
      "chapter": 42,
      "verse": 6,
      "text_ar": "أهلاً، بل وأنا غير أهلٍ وأنا خاطئة، أن أُدخل إلى مسكنه، تماماً كما كنتُ معه في الفردوس، بلا انفصال الواحد عن الآخر؛ تماماً كما في تعدينا، كنا"
    },
    {
      "chapter": 42,
      "verse": 7,
      "text_ar": "(كلينا) قد ضللنا وتعدينا وصيتك، ولكنا لم ننفصل. هكذا يا رب، لا"
    },
    {
      "chapter": 42,
      "verse": 8,
      "text_ar": "تفصلنا الآن.' ولكن بعد أن صلّت، شخصت نحو السماء وأطلقت تنهيدة عالية وضربت صدرها وقالت: 'يا إله الكل، تقبل روحي'، وفي الحال أسلمت روحها لله."
    },
    {
      "chapter": 43,
      "verse": 1,
      "text_ar": "وجاء ميخائيل وعلّم شيثاً كيف يعدّ حواء للدفن. وجاء ثلاثة ملائكة ودفنوا جسدها حيث كان جسد آدم وهابيل. وبعد ذلك تحدث"
    },
    {
      "chapter": 43,
      "verse": 2,
      "text_ar": "ميخائيل إلى شيث وقال: 'هكذا جهّز كل إنسان يموت إلى يوم القيامة'. وبعد أن أعطاه هذه القاعدة، هو"
    }
  ],
  "book_code": "APMO"
}
